import { deepClone } from "../../commonHelpers/utils";
import { createDisplayingElements } from "./createDisplayingElements";
export const handleElementsPriority = (children, widthProps, displayingElements) => {
    let displayingElementsClone = deepClone(displayingElements);
    for (let i = 0; i <= children.length - 1 && widthProps.requiredWidth <= widthProps.width; i++) {
        const requiredElementsInd = [];
        children[i].childNodes.forEach((el, ind) => {
            if (el.classList.contains("zen-toolbar__item-priority")) {
                requiredElementsInd.push(ind);
            }
        });
        for (let j = 0; j < requiredElementsInd.length; j++) {
            displayingElementsClone = createDisplayingElements(i, children, displayingElementsClone, widthProps)(requiredElementsInd[j]);
        }
    }
    return displayingElementsClone;
};
